<?php require 'config.php';require 'includes/functions.php';require_login();verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$pid=(int)$_POST['product_id'];$rating=max(1,min(5,(int)$_POST['rating']));$comment=trim($_POST['comment']??'');$s=$pdo->prepare("INSERT INTO reviews(product_id,user_id,rating,comment) VALUES(?,?,?,?)");$s->execute([$pid,current_user()['id'],$rating,$comment]);flash('Thanks for your review.');go('product.php?id='.$pid);}$pid=(int)($_GET['product_id']??0);$title='Review';require 'includes/header.php';?><div class="formbox"><h1>Write a review</h1><form method="post"><?=csrf_field()?><input type="hidden" name="product_id" value="<?=$pid?>"><label>Rating<select name="rating"><option value="5">5 - Excellent</option><option value="4">4 - Very good</option><option value="3">3 - Good</option><option value="2">2 - Fair</option><option value="1">1 - Poor</option></select></label><label>Review<textarea name="comment" maxlength="1000"></textarea></label><button class="button dark">Submit review</button></form></div><?php require 'includes/footer.php';?>